  eprintln_hit: { kind: "set", addSql: `INSERT OR IGNORE INTO "eprintln_hit" ("path", "line_no") VALUES (?, ?)`, delSql: `DELETE FROM "eprintln_hit" WHERE "path" = ? AND "line_no" = ?` },
  gate_threshold: { kind: "set", addSql: `INSERT OR IGNORE INTO "gate_threshold" ("stage", "min_rank") VALUES (?, ?)`, delSql: `DELETE FROM "gate_threshold" WHERE "stage" = ? AND "min_rank" = ?` },
  program: { kind: "set", addSql: `INSERT OR IGNORE INTO "program" ("name") VALUES (?)`, delSql: `DELETE FROM "program" WHERE "name" = ?` },
